#!/usr/bin/env python3
"""Generates checkpoint4/rtl/dme_halfsine_rom.sv.

The interrogation pulse envelope is a 7 us half-sine, 700 samples at
100 MHz, peak 2047. The course ground station uses the same shape for its
replies (pulseBRAM.v). Its demodulator and reply generator only accept
pulses whose detected width is 6.5 to 7.5 us, which this shape gives.
"""
import math
import pathlib

SAMPLES = 700
PEAK = 2047

values = [round(PEAK * math.sin(math.pi * n / SAMPLES)) for n in range(SAMPLES)]
lines = [
    "`timescale 1ns/1ps",
    "",
    "// Generated by checkpoint4/sim/gen_halfsine_rom.py. Do not edit.",
    f"// {SAMPLES}-sample half-sine pulse envelope, peak {PEAK}, registered read.",
    "module dme_halfsine_rom (",
    "    input  logic        clk,",
    "    input  logic [9:0]  addr,",
    "    output logic [11:0] data",
    ");",
    f"    logic [11:0] rom [0:{SAMPLES - 1}];",
    "",
    "    initial begin",
]
lines += [f"        rom[{n}] = 12'd{v};" for n, v in enumerate(values)]
lines += [
    "    end",
    "",
    "    always_ff @(posedge clk)",
    f"        data <= (addr < 10'd{SAMPLES}) ? rom[addr] : 12'd0;",
    "endmodule",
    "",
]
out = pathlib.Path(__file__).resolve().parent.parent / "rtl" / "dme_halfsine_rom.sv"
out.write_text("\n".join(lines))
print(f"wrote {out}")
